# Search more thoroughly for any 1962 monthly data
with open('/app/resources/treasury_bulletin_1964_12.txt', 'r') as f:
    content = f.read()

# Look for pattern with 1962 and month names
import re

# Find all occurrences of lines with 1962 and month names
lines = content.split('\n')
for i, line in enumerate(lines):
    if '1962' in line and ('January' in line or 'February' in line or 'Mar.' in line or 'Apr.' in line or 'May' in line or 'June' in line):
        if 'Railroad' in line:
            print(f"Line {i}: {line[:200]}")

# Also search for pattern like "1962-Jan" or "1962-Feb"
for i, line in enumerate(lines):
    if re.search(r'1962.*Jan', line) or re.search(r'1962.*Feb', line):
        if 'Railroad' in line:
            print(f"Line {i}: {line[:200]}")
EOF
